// Pure regex parser for French supermarket receipts (raw OCR text in, schema v1 JSON out).
// No model, no network. Works in browsers, Node and JavaScriptCore.

const STORES = [
  ['E.Leclerc', /\bE\.?\s?LECLERC\b/], ['Carrefour', /\bCARREFOUR\b|\bCRF[- ]CITY\b/],
  ['Monoprix', /\bMONOPRIX\b/], ['Intermarché', /\bINTERMARCH[EÉ]\b/], ['Lidl', /\bLIDL\b/],
  ['Biocoop', /\bBIOCOOP\b/], ['La Vie Claire', /\bLA VIE CLAIRE\b/], ['Naturalia', /\bNATURALIA\b/],
  ['Auchan', /\bAUCHAN\b|\bSIMPLY\b/], ['Aldi', /\bA\s?L\s?D\s?I\b/], ['Super U', /\b(SUPER|HYPER|MARCHE) U\b|\bU EXPRESS\b/],
  ['Franprix', /\bFRANPRIX\b/], ['Casino', /\bCASINO\b/], ['Picard', /\bPICARD\b/], ['Grand Frais', /\bGRAND FRAIS\b/],
];
const MONTHS = { janv: 1, janvier: 1, fevr: 2, fevrier: 2, mars: 3, avr: 4, avril: 4, mai: 5, juin: 6, juil: 7, juillet: 7,
  aout: 8, sept: 9, septembre: 9, oct: 10, octobre: 10, nov: 11, novembre: 11, dec: 12, decembre: 12 };

const AMOUNT = String.raw`-?\s?\d{1,4}[.,]\d{2}`;
const TAIL = new RegExp(String.raw`(${AMOUNT})\s*(?:€|EUR|E)?\s*\*?(?:\s+([A-Z]|\d{1,2}))?\s*$`);
const QTY_LINE = new RegExp(String.raw`^(\d{1,3})\s*x\s*(\d{1,4}[.,]\d{2})\s*(?:€|EUR)?(?:\s+(${AMOUNT}))?\s*(?:€|EUR)?(?:\s+[A-Z])?\s*$`, 'i');
const WEIGHT_LINE = new RegExp(String.raw`^(\d{1,3}[.,]\d{1,4})\s*kg\s*x\s*(\d{1,4}[.,]\d{2})\s*(?:€|EUR)?\s*/\s*kg(?:\s+(${AMOUNT}))?`, 'i');
const INLINE_QTY = /^(.*\S)\s+(\d{1,3})\s*x\s*(\d{1,4}[.,]\d{2})\s*(?:€|EUR)?\s*$/i;

const FINAL_TOTAL = /(\bA\s?PAYER\b|\bMONTANT\s+DU\b|\bNET\s+A\s+PAYER\b|\bTOTAL\s+AVEC\s+AVANTAGES\b|^=?\s*T\s?[O0]\s?T\s?A\s?L\b(?!\s+(ACHATS|ALIMENTAIRE|NON|DES|REMISES|AVANT|POINTS|AVANTAGES|TVA|HT|ELIGIBLE))|^TOTAL\s*(€|EUR)|\bTOTAL\s+\d+\s+ARTICLES?\b)/;
const SUBTOTAL = /\bTOTAL\b|\bSOUS[- ]TOTAL\b|\bEUR[*xX]?\s*TOT\b/;
const PAYMENT = /\b(CB|CARTE|CARTE BANCAIRE|CARTE BLEUE|CARTE CREDIT|EMV|SANS CONTACT|ESPECES|COMPTANT|CHEQUE|TICKET RESTO|TITRE RESTAURANT|TRD|RENDU|A RENDRE|RETOUR|MONNAIE|BON D.ACHAT|BON REDUCTION)\b/;
const POST_TOTAL_START = /\bTOTAL\s+(ACHATS|AVANT\s+REMISES?)\b|\bEUR[*xX]?\s*TOT\b|\bSOUS[- ]TOTAL\b/;
const PHONE = /\b0\d([ .]?\d{2}){4}\b/;
const DISCOUNT = /\b(REMISE|PROMO|AVANTAGE|REDUCTION|BON|COUPON|FIDELITE|IMMEDIATE|LOT|OFFRE)\b/;
const VAT_ROW = /^(?:([A-Z]|\d{1,2})\s+)?(\d{1,2}[.,]\d{1,2})\s*%\s+(?:TVA\s+DE\s+)?(\d+[.,]\d{2})\s+(\d+[.,]\d{2})(?:\s+(\d+[.,]\d{2}))?/;
const NOISE = /\b(TEL|T[EÉ]L[EÉ]PHONE|SIRET|SIREN|RCS|TVA\s+INTRA|NAF|WWW|HTTP|BIENVENUE|MERCI|HORAIRES?|OUVERT|LUNDI|MARDI|DIMANCHE|CAISSE|CAISSIER|VENDEUR|OPERATEUR|TICKET|NOMBRE|ARTICLES?\b|DESCRIPTION|DESIGNATION|QTE|MONTANT\s*€?$|SOLDE|CUMUL|POINTS|S.MILES|VIGNETTE|CONSERVER|GARANTIE)\b/;

function normalizeLine(raw) {
  return raw.normalize('NFC')
    .replace(/[хХ×]/g, 'x')        // Cyrillic x/X and multiplication sign from Apple Vision
    .replace(/(\d)\s*[*]\s*(?=\d)/g, '$1 x ')
    .replace(/(\d)[.,]\s(\d{2})\b/g, '$1.$2')      // "0. 42" -> "0.42"
    .replace(/(\d)\s?k[g9]\b/gi, '$1kg')           // "0.210 k9" -> "0.210kg"
    .replace(/\/\s?k[g9]\b/gi, '/kg')
    .replace(/(\d)%(\d{2})/g, '$1.$2%')            // Leclerc "5%50" -> "5.50%"
    .replace(/(\S)-\s(\d)/g, '$1 -$2')             // Monoprix "LABEL- 0,09" -> "LABEL -0,09"
    .replace(/\s+/g, ' ').trim();
}

const num = (s) => (s == null ? null : Number(String(s).replace(/\s/g, '').replace(',', '.')));
const round2 = (x) => Math.round(x * 100) / 100;
const up = (s) => s.toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

function parseDate(text) {
  const t = up(text);
  let m = t.match(/\b(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4}|\d{2})\b/);
  let d, mo, y;
  if (m) [, d, mo, y] = m;
  else if ((m = t.match(/\b(\d{1,2})\s+([A-Z]{3,9})\.?\s+(\d{4})\b/)) && MONTHS[m[2].toLowerCase()]) { d = m[1]; mo = MONTHS[m[2].toLowerCase()]; y = m[3]; }
  else return null;
  y = String(y).length === 2 ? 2000 + Number(y) : Number(y);
  if (+mo < 1 || +mo > 12 || +d < 1 || +d > 31) return null;
  const tm = t.match(/\b([01]?\d|2[0-3])[:H](\d{2})(?::(\d{2}))?\b/);
  const iso = `${y}-${String(mo).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  return tm ? `${iso}T${tm[1].padStart(2, '0')}:${tm[2]}:${tm[3] || '00'}` : iso;
}

function parseReceipt(rawText) {
  const lines = rawText.split(/\r?\n/).map(normalizeLine).filter(Boolean);
  const U = lines.map(up);
  const out = { schema: 'receipt/v1', store: null, date: null, currency: 'EUR', lines: [], totals: {}, vat: [], warnings: [], confidence: 0 };

  const letters = U.map((l) => l.replace(/0/g, 'O').replace(/1/g, 'I'));  // OCR digit/letter confusions in logos
  for (const [name, re] of STORES) if (U.some((l, i) => re.test(l) || re.test(letters[i]))) { out.store = name; break; }
  for (const l of U) { const d = parseDate(l); if (d && (!out.date || d.length > out.date.length)) out.date = d; if (out.date?.includes('T')) break; }

  // Final total: prefer the keyword line whose amount matches a payment line.
  const amountOf = (i) => { const m = U[i].match(TAIL); return m ? num(m[1]) : null; };
  const payments = U.map((l, i) => (PAYMENT.test(l) && !FINAL_TOTAL.test(l) ? amountOf(i) : null)).filter((x) => x != null && x > 0);
  const totalIdx = U.map((l, i) => (FINAL_TOTAL.test(l) && amountOf(i) > 0 ? i : -1)).filter((i) => i >= 0);
  let finalIdx = totalIdx.find((i) => payments.some((p) => Math.abs(p - amountOf(i)) < 0.011)) ?? totalIdx[totalIdx.length - 1] ?? -1;
  if (finalIdx >= 0) out.totals.total = amountOf(finalIdx);
  const postStart = U.findIndex((l) => POST_TOTAL_START.test(l));
  const firstTotal = postStart >= 0 && (finalIdx < 0 || postStart < finalIdx) ? postStart : finalIdx;
  out.totals.paid = payments.find((p) => Math.abs(p - (out.totals.total ?? -1)) < 0.011) ?? null;
  for (const u of U) {
    const vat = u.match(VAT_ROW);
    if (vat && /%/.test(u) && !out.vat.some((v) => v.code === (vat[1] || null))) out.vat.push({ code: vat[1] || null, rate: num(vat[2]) });
  }

  let pending = null;       // label seen without a price, waiting for a qty/weight line
  let inPostTotal = false;  // between first subtotal and final total: only discount details count
  const end = finalIdx >= 0 ? finalIdx : lines.length;

  for (let i = 0; i < end; i++) {
    const L = lines[i], u = U[i];
    if (i >= firstTotal && firstTotal >= 0) inPostTotal = true;
    if (VAT_ROW.test(u) && /%/.test(u)) continue;

    const w = L.match(WEIGHT_LINE);
    if (w && !inPostTotal) {
      const qty = num(w[1]), unitPrice = num(w[2]), total = w[3] != null ? num(w[3]) : round2(qty * unitPrice);
      const target = pending ?? (w[3] == null ? out.lines[out.lines.length - 1] : null);
      if (target && !target.is_discount) Object.assign(target, { qty, unit: 'kg', unit_price: unitPrice, total: target.total ?? total });
      else out.lines.push(item(pending?.label ?? '?', qty, 'kg', unitPrice, total, null, i));
      if (pending) { out.lines.push(pending); pending = null; }
      continue;
    }
    const q = L.match(QTY_LINE);
    if (q && !inPostTotal) {
      const qty = num(q[1]), unitPrice = num(q[2]), total = q[3] != null ? num(q[3]) : null;
      if (pending) { Object.assign(pending, { qty, unit_price: unitPrice, total: total ?? round2(qty * unitPrice) }); out.lines.push(pending); pending = null; }
      else if (out.lines.length) Object.assign(out.lines[out.lines.length - 1], { qty, unit_price: unitPrice });
      continue;
    }
    if (SUBTOTAL.test(u)) { const a = amountOf(i); if (a != null && a > 0 && POST_TOTAL_START.test(u) && out.totals.subtotal == null) out.totals.subtotal = a; continue; }
    const t = L.match(TAIL);
    const negative = t && num(t[1]) < 0;
    if (!(negative && (DISCOUNT.test(u) || !PAYMENT.test(u))) && (PAYMENT.test(u) || NOISE.test(u) || PHONE.test(u) || /^[>=*\s]+$/.test(L))) continue;

    if (!t) {
      if (!inPostTotal && /[A-Za-z]{2}/.test(L) && !/^>+/.test(L) && i > 0 && looksLikeLabel(L, U[i + 1])) pending = item(L, 1, 'piece', null, null, null, i);
      continue;
    }
    const amount = num(t[1]);
    let label = L.slice(0, t.index).replace(/[\s.:*-]+$/, '').replace(/^[*>\s]+/, '');
    if (!/[A-Za-z]{2}/.test(label)) continue;
    const discountWord = /^(REMISE|PROMO|REDUC|AVANTAGE|BON|COUPON)/.test(up(label));
    if (amount < 0 || discountWord || (inPostTotal && DISCOUNT.test(up(label)))) {
      const d = { ...item(label, 1, 'piece', null, -Math.abs(amount), t[2], i), is_discount: true };
      if (amount > 0) d.flags.push('sign_inferred');
      out.lines.push(d);
      continue;
    }
    if (inPostTotal) continue;
    let qty = 1, unitPrice = amount;
    const iq = label.match(INLINE_QTY);
    if (iq) { label = iq[1]; qty = num(iq[2]); unitPrice = num(iq[3]); }
    pending = null;
    out.lines.push(item(label, qty, 'piece', unitPrice, amount, t[2], i));
  }

  const vatCodes = new Map(out.vat.filter((v) => v.code).map((v) => [v.code, v.rate]));
  for (const l of out.lines) {
    if (l.unit_price == null && l.total != null) l.unit_price = round2(l.total / (l.qty || 1));
    if (l.vat_code && vatCodes.has(l.vat_code)) l.vat_rate = vatCodes.get(l.vat_code);
    if (!l.is_discount && l.unit === 'piece' && Math.abs(round2(l.qty * l.unit_price) - l.total) > 0.011) l.flags.push('qty_x_price_mismatch');
    if (l.unit === 'kg' && Math.abs(l.qty * l.unit_price - l.total) > 0.02) l.flags.push('weight_x_price_mismatch');
  }
  const sumLines = round2(out.lines.reduce((s, l) => s + (l.total ?? 0), 0));
  out.totals.lines_sum = sumLines;
  out.totals.discounts = round2(out.lines.filter((l) => l.is_discount).reduce((s, l) => s + l.total, 0));
  const ref = out.totals.total;
  const matches = ref != null && Math.abs(sumLines - ref) < 0.011;
  if (ref == null) out.warnings.push('no_total_found');
  else if (!matches) out.warnings.push(`sum_mismatch: lines ${sumLines} vs total ${ref}`);
  out.confidence = round2((out.store ? 0.15 : 0) + (out.date ? 0.15 : 0) + (ref != null ? 0.2 : 0) + (matches ? 0.4 : 0)
    + 0.1 * (out.lines.filter((l) => !l.flags.length).length / Math.max(1, out.lines.length)));
  return out;
}

function looksLikeLabel(line, nextUpper = '') {
  return QTY_LINE.test(nextUpper.replace(/[хХ×]/g, 'X')) || WEIGHT_LINE.test(nextUpper);
}

function item(label, qty, unit, unitPrice, total, vatCode, lineNo) {
  return { label: label.trim(), qty, unit, unit_price: unitPrice, total, is_discount: false, vat_code: vatCode ?? null, source_line: lineNo, flags: [] };
}

// Joins the OCR lines of several photos of one long receipt (top to bottom). Where two photos overlap, the lines of the
// next photo that repeat the end of the previous one are dropped (up to 2 cut lines at the photo edge are skipped too).
function stitchParts(parts) {
  const key = (l) => up(normalizeLine(String(l))).replace(/[^A-Z0-9]/g, '');
  const out = [];
  for (const part of parts) {
    const lines = (Array.isArray(part) ? part : String(part || '').split(/\r?\n/)).map(String).filter((l) => l.trim());
    const a = out.map(key), b = lines.map(key);
    let skip = 0;
    for (let k = Math.min(a.length, b.length, 30); k > 0 && !skip; k--) {
      for (let o = 0; o <= 2 && o + k <= b.length && !skip; o++) {
        const same = b.slice(o, o + k).filter((x, i) => x && x === a[a.length - k + i]).length;
        if (same >= Math.ceil(k * 0.6) && (k > 1 ? same >= 2 : b[o].length >= 8)) skip = o + k;
      }
    }
    out.push(...lines.slice(skip));
  }
  return out;
}

const SECRET = "__WEBHOOK_SECRET__";
const req = $input.first().json;
const headers = req.headers || {};
const stop = (http_status, reply) => [{ json: { http_status, reply, needs_repair: false } }];
if (headers["x-trigger-secret"] !== SECRET) return stop(401, { error: "unauthorized" });

const body = req.body || {};
const parts = Array.isArray(body.parts) ? body.parts.filter((p) => Array.isArray(p) || typeof p === "string") : [];
const rawLines = (parts.length ? stitchParts(parts) : Array.isArray(body.lines) ? body.lines : typeof body.text === "string" ? body.text.split(/\r?\n/) : [])
  .map((l) => String(l)).filter((l) => l.trim());
if (!rawLines.length) return stop(400, { error: "lines required" });

const parsed = parseReceipt(rawLines.join("\n"));
const SHOPS = { "La Vie Claire": 1, Biocoop: 2, Naturalia: 3, Carrefour: 4, Monoprix: 5 };
const store = parsed.store || body.store_hint || null;
const receipt = {
  store, shopping_location_id: SHOPS[store] || null,
  date: parsed.date || body.date_hint || null,
  total: parsed.totals.total ?? null, subtotal: parsed.totals.subtotal ?? null, currency: "EUR",
  lines: parsed.lines.map((l) => ({ label: l.label, product_id: null, qty: l.qty, unit: l.unit, unit_price: l.unit_price,
    total: l.total, is_discount: l.is_discount, vat_code: l.vat_code, matched_by: null, flags: l.flags })),
  lines_sum: parsed.totals.lines_sum, confidence: parsed.confidence, parser: "regex-v1", raw_ocr: rawLines.join("\n"), photos: Math.max(1, parts.length),
};
const warnings = [...parsed.warnings];
if (body.image_b64) warnings.push("image_ignored: send OCR lines, the server does not read photos");
const needs_repair = parsed.warnings.some((w) => /sum_mismatch|no_total_found/.test(w)) || !parsed.lines.length;

const SYSTEM = `Tu transformes le texte OCR d'un ticket de caisse de supermarché français en lignes d'articles structurées.
Particularités des tickets français à gérer:
- Abréviations de caisse: développe-les en nom lisible (« CR.FR.EPAIS 30% » -> « Crème fraîche épaisse 30% »,
  « YT NAT » -> « Yaourt nature », « JB BLANC » -> « Jambon blanc »). Garde la marque si elle apparaît.
- Quantités: « 2 X 1,49 » ou « 2 x 1.49 € » sur la ligne suivante = quantity 2, unit_price 1.49.
- Poids: « 0,512 kg x 3,99 €/kg » = quantity 0.512, unit "kg", unit_price 3.99.
- Remises: lignes « REMISE », « REM. FIDELITE », « BON DE REDUCTION », « -0,50 » : rattache la remise à l'article
  juste au-dessus (discount positif), ne crée pas d'article.
- Consignes, sacs, cartes cadeaux: is_food = false.
- Ignore les lignes de total, TVA, paiement, carte bancaire, rendu monnaie, adresse, SIRET, horaires.
- Décimales françaises: la virgule est le séparateur décimal.
- Ne devine pas un prix illisible: mets null et baisse confidence.
- Recopie la ligne source exacte dans raw_line.
Réponds uniquement avec l'objet JSON demandé.`;
const ITEM = {
  type: "object", additionalProperties: false,
  required: ["raw_line", "name", "brand", "quantity", "unit", "unit_price", "line_total", "discount", "is_food", "category"],
  properties: {
    raw_line: { type: "string" }, name: { type: "string" }, brand: { type: ["string", "null"] }, quantity: { type: "number" },
    unit: { type: "string", enum: ["piece", "kg", "g", "l", "ml", "lot"] }, unit_price: { type: ["number", "null"] },
    line_total: { type: ["number", "null"] }, discount: { type: ["number", "null"] }, is_food: { type: "boolean" },
    category: { type: ["string", "null"] },
  },
};
const SCHEMA = {
  type: "object", additionalProperties: false, required: ["store", "purchase_date", "currency", "items", "total", "confidence"],
  properties: { store: { type: ["string", "null"] }, purchase_date: { type: ["string", "null"] }, currency: { type: "string", enum: ["EUR"] },
    total: { type: ["number", "null"] }, confidence: { type: "number" }, items: { type: "array", items: ITEM } },
};
const repair_body = {
  models: ["nvidia/nemotron-3-super-120b-a12b:free"],
  reasoning: { enabled: false }, temperature: 0, max_tokens: Math.min(4000, 60 * rawLines.length + 200),
  provider: { require_parameters: true },
  response_format: { type: "json_schema", json_schema: { name: "receipt", strict: true, schema: SCHEMA } },
  plugins: [{ id: "response-healing" }],
  messages: [{ role: "system", content: SYSTEM },
    { role: "user", content: `Enseigne probable: ${store || "inconnue"}\nLignes OCR (une par ligne, dans l'ordre):\n${rawLines.join("\n")}` }],
};
return [{ json: { receipt, warnings, needs_repair, repair_body } }];

const QUOTA_RESERVE = 15;
const parsed = $("Parse").first().json;
const quota = $input.first().json || {};
const daily = quota.data && quota.data.free_model_daily_requests;
const remaining = daily && typeof daily.remaining === "number" ? daily.remaining : null;
const use_openrouter = !quota.error && (remaining === null || remaining > QUOTA_RESERVE);
return [{ json: { ...parsed, use_openrouter, quota_remaining: remaining } }];

// Match an abbreviated receipt label to a Grocy product.
// products: [{ id, name, userfields: { receipt_aliases: "KEY1\nKEY2" } }]

const ABBREV = {
  SS: 'SANS', 'S/': 'SANS', GLUT: 'GLUTEN', CHOC: 'CHOCOLAT', CHOCO: 'CHOCOLAT', LT: 'LAIT', FROM: 'FROMAGE',
  CR: 'CREME', CREM: 'CREME', FRAI: 'FRAIS', FRAICH: 'FRAICHE', EPAIS: 'EPAISSE', ECR: 'ECREME', NR: 'NOIR',
  BLC: 'BLANC', MLU: 'MOULE', MOUL: 'MOULE', DX: 'DOUX', PRUN: 'PRUNEAUX', CHEV: 'CHEVRE', PTIT: 'PETIT',
  PT: 'PETIT', BISC: 'BISCUIT', YAO: 'YAOURT', YRT: 'YAOURT', CONF: 'CONFITURE', LEG: 'LEGUMES',
  NAT: 'NATURE', SCE: 'SAUCE', HLE: 'HUILE', JB: 'JAMBON', PDT: 'POMME DE TERRE', VEG: 'VEGETAL',
  OEUF: 'OEUFS', BEUR: 'BEURRE', MASCARP: 'MASCARPONE', EMMENT: 'EMMENTAL', LACT: 'LACTOSE',
};
const STOP = new Set(['DE', 'DU', 'DES', 'LA', 'LE', 'LES', 'AU', 'AUX', 'ET', 'A', 'D', 'L', 'EN', 'X']);
const SIZE = /\b(\d+(?:[.,]\d+)?)\s*(G|GR|KG|CL|ML|L|P|PCS|X\d+)\b|\bX\s?\d+\b|\b\d+X\d*\b/g;

function normalizeLabel(label) {
  const base = label.toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/Œ/g, 'OE').replace(/[’'`]/g, ' ').replace(/[^A-Z0-9/., ]/g, ' ');
  const sizes = (base.match(SIZE) || []).map((s) => s.replace(/\s|,/g, '').replace('GR', 'G'));
  const words = base.replace(SIZE, ' ').replace(/[./,]/g, ' ').split(/\s+/)
    .map((w) => w.replace(/0/g, 'O'))                 // OCR "CH0C0" -> "CHOCO"
    .filter((w) => w && !/^\d+$/.test(w))
    .flatMap((w) => (ABBREV[w] || w).split(' '))
    .filter((w) => !STOP.has(w));
  return { key: words.join(' '), words, sizes };
}

function jaroWinkler(a, b) {
  if (a === b) return 1;
  const range = Math.max(0, Math.floor(Math.max(a.length, b.length) / 2) - 1);
  const am = new Array(a.length).fill(false), bm = new Array(b.length).fill(false);
  let m = 0;
  for (let i = 0; i < a.length; i++) for (let j = Math.max(0, i - range); j < Math.min(b.length, i + range + 1); j++)
    if (!bm[j] && a[i] === b[j]) { am[i] = bm[j] = true; m++; break; }
  if (!m) return 0;
  let t = 0, k = 0;
  for (let i = 0; i < a.length; i++) if (am[i]) { while (!bm[k]) k++; if (a[i] !== b[k]) t++; k++; }
  const jaro = (m / a.length + m / b.length + (m - t / 2) / m) / 3;
  let p = 0; while (p < 4 && a[p] === b[p]) p++;
  return jaro + p * 0.1 * (1 - jaro);
}

const trigrams = (s) => { const g = new Set(); const t = `  ${s} `; for (let i = 0; i < t.length - 2; i++) g.add(t.slice(i, i + 3)); return g; };
function trigramDice(a, b) {
  const A = trigrams(a), B = trigrams(b); let n = 0; for (const g of A) if (B.has(g)) n++;
  return (2 * n) / (A.size + B.size || 1);
}

// Each receipt word finds its best partner in the product name (receipt words are prefixes or truncations).
function tokenScore(rw, pw) {
  if (!rw.length || !pw.length) return 0;
  const per = rw.map((r) => Math.max(...pw.map((p) => (p.startsWith(r) && r.length >= 3 ? 0.97 : jaroWinkler(r, p)))));
  return per.reduce((s, x) => s + x, 0) / per.length;
}

function matchLabel(label, products, { threshold = 0.82, margin = 0.05 } = {}) {
  const n = normalizeLabel(label);
  for (const p of products) {
    const aliases = (p.userfields?.receipt_aliases || '').split('\n').map((s) => s.trim()).filter(Boolean);
    if (aliases.includes(n.key)) return { product_id: p.id, score: 1, method: 'alias', key: n.key, candidates: [] };
  }
  const scored = products.map((p) => {
    const pn = normalizeLabel(p.name);
    const s = 0.6 * tokenScore(n.words, pn.words) + 0.4 * trigramDice(n.key, pn.key)
      + (n.sizes.length && n.sizes.some((z) => pn.sizes.includes(z)) ? 0.05 : 0);
    return { product_id: p.id, name: p.name, score: Math.round(Math.min(1, s) * 1000) / 1000 };
  }).sort((a, b) => b.score - a.score);
  const [best, second] = scored;
  const auto = best && best.score >= threshold && (!second || best.score - second.score >= margin);
  return { product_id: auto ? best.product_id : null, score: best?.score ?? 0, method: auto ? 'fuzzy' : 'needs_confirmation', key: n.key, candidates: scored.slice(0, 5) };
}

const GROCY = "http://grocy/api";
const GROCY_KEY = "__GROCY_API_KEY__";
const x = $("Parse").first().json;
if (x.reply) return [{ json: { http_status: x.http_status, reply: x.reply } }];

const receipt = { ...x.receipt };
const warnings = [...x.warnings];
const round2 = (v) => Math.round(v * 100) / 100;

const KEYS = { groq: "__GROQ_API_KEY__", mistral: "__MISTRAL_API_KEY__", gemini: "__GEMINI_API_KEY__" };
const GEMINI_MODEL = "gemini-2.5-flash";
let plan = null;
try { plan = $("Repair plan").first().json; } catch (e) { plan = null; }

function applyRepair(data, source) {
  if (!data || !Array.isArray(data.items) || !data.items.length) return "llm_repair_failed: " + source;
  const lines = [];
  for (const it of data.items) {
    lines.push({ label: it.name || it.raw_line, product_id: null, qty: it.quantity || 1, unit: it.unit === "kg" ? "kg" : "piece",
      unit_price: it.unit_price, total: it.line_total, is_discount: false, vat_code: null, matched_by: null, flags: ["llm_corrected"] });
    if (it.discount) lines.push({ label: "REMISE " + (it.name || ""), product_id: null, qty: 1, unit: "piece", unit_price: null,
      total: -Math.abs(it.discount), is_discount: true, vat_code: null, matched_by: null, flags: ["llm_corrected"] });
  }
  const sum = round2(lines.reduce((s, l) => s + (l.total || 0), 0));
  const total = receipt.total ?? data.total ?? null;
  if (total === null || Math.abs(sum - total) >= 0.011) return `llm_repair_rejected: ${source} lines ${sum} vs total ${total}`;
  Object.assign(receipt, { lines, lines_sum: sum, total, parser: "regex-v1+llm:" + source });
  if (!receipt.store && data.store) receipt.store = data.store;
  if (!receipt.date && data.purchase_date) receipt.date = data.purchase_date;
  for (let i = warnings.length - 1; i >= 0; i--) if (/sum_mismatch|no_total_found/.test(warnings[i])) warnings.splice(i, 1);
  return null;
}
const parseJson = (t) => { try { return JSON.parse(String(t).replace(/^```(?:json)?|```$/g, "").trim()); } catch (e) { return null; } };

if (x.needs_repair && plan) {
  let repaired = false;
  if (!plan.use_openrouter) warnings.push("llm_repair_skipped: quota " + plan.quota_remaining);
  else {
    let llm = null;
    try { llm = $("OpenRouter repair").first().json; } catch (e) { llm = null; }
    let content = null;
    try { content = llm.choices[0].message.content; } catch (e) { content = null; }
    const why = applyRepair(parseJson(content), "openrouter:" + ((llm && llm.model) || "free"));
    if (why) warnings.push(why); else repaired = true;
  }
  const rb = x.repair_body;
  const schema = rb.response_format.json_schema.schema;
  const openai = (model) => ({ model, temperature: 0, max_tokens: rb.max_tokens, messages: rb.messages,
    response_format: { type: "json_schema", json_schema: { name: "receipt", strict: true, schema } } });
  const HOSTED = [
    { id: "groq", url: "https://api.groq.com/openai/v1/chat/completions", body: openai("qwen/qwen3.8-27b"),
      headers: (k) => ({ Authorization: "Bearer " + k }), text: (r) => r.choices[0].message.content, model: (r) => r.model || "qwen/qwen3.8-27b" },
    { id: "mistral", url: "https://api.mistral.ai/v1/chat/completions", body: openai("ministral-14b-latest"),
      headers: (k) => ({ Authorization: "Bearer " + k }), text: (r) => r.choices[0].message.content, model: (r) => r.model || "ministral-14b-latest" },
    { id: "gemini", url: "https://generativelanguage.googleapis.com/v1beta/models/" + GEMINI_MODEL + ":generateContent",
      body: { systemInstruction: { parts: [{ text: rb.messages[0].content }] }, contents: [{ role: "user", parts: [{ text: rb.messages[1].content }] }],
        generationConfig: { temperature: 0, maxOutputTokens: rb.max_tokens, responseMimeType: "application/json", responseJsonSchema: schema,
          thinkingConfig: { thinkingBudget: 0 } } },
      headers: (k) => ({ "x-goog-api-key": k }), text: (r) => r.candidates[0].content.parts[0].text, model: (r) => r.modelVersion || GEMINI_MODEL },
  ];
  for (const p of HOSTED) {
    if (repaired || !KEYS[p.id] || KEYS[p.id].startsWith("__")) continue;
    try {
      const r = await this.helpers.httpRequest({ method: "POST", url: p.url, json: true, timeout: 20000,
        headers: { ...p.headers(KEYS[p.id]), "Content-Type": "application/json" }, body: p.body });
      const why = applyRepair(parseJson(p.text(r)), p.id + ":" + p.model(r));
      if (why) warnings.push(why); else repaired = true;
    } catch (e) { warnings.push("llm_repair_failed: " + p.id + " " + String(e.message).slice(0, 120)); }
  }
  if (repaired) for (let i = warnings.length - 1; i >= 0; i--) if (/^llm_repair_(failed|rejected|skipped)/.test(warnings[i])) warnings.splice(i, 1);
}

const products = (await this.helpers.httpRequest({ method: "GET", url: GROCY + "/objects/products", json: true,
  headers: { "GROCY-API-KEY": GROCY_KEY } })).filter((p) => p.active == 1);
const matches = [];
receipt.lines.forEach((line, i) => {
  if (line.is_discount) return;
  const m = matchLabel(line.label, products);
  if (m.product_id) { line.product_id = m.product_id; line.matched_by = m.method; }
  matches.push({ line_index: i, product_id: m.product_id, score: m.score, method: m.method, key: m.key,
    candidates: m.candidates.slice(0, 5).map((c) => ({ product_id: c.product_id, name: c.name, score: c.score })) });
});
receipt.sum_matches_total = receipt.total !== null && Math.abs(receipt.lines_sum - receipt.total) < 0.011;
return [{ json: { http_status: 200, reply: { receipt, warnings, matches } } }];
